arguments.newString:
import os


def read_file(root: str, name: str):
    root_real = os.path.realpath(root)
    path = os.path.realpath(os.path.join(root_real, name))
    if not (path == root_real or path.startswith(root_real + os.sep)):
        raise ValueError("path escapes root")
    with open(path) as f:
        return f.read()
